schedule_callback.pre_process_code:
import datetime
vars['callback_ok'] = 'no'
vars['bank_event'] = 'none'
vars['callback_window'] = ''
try:
    now = datetime.datetime.fromisoformat(str(vars.get('now', '')).replace('Z', '+00:00'))
    today = now.date()
    holidays = ['2026-10-26','2026-11-11','2026-11-26','2026-12-25','2027-01-01']
    next_day = today + datetime.timedelta(days=1)
    while next_day.weekday() >= 5 or next_day.isoformat() in holidays:
        next_day += datetime.timedelta(days=1)
    vars['callback_window'] = today.isoformat() + ' or ' + next_day.isoformat() + ', 10:00–19:00, later than now'
    d = datetime.date.fromisoformat(str(vars.get('callback_date', '')))
    t = datetime.time.fromisoformat(str(vars.get('callback_time', '')))
    stamp = datetime.datetime.combine(d, t).replace(tzinfo=now.tzinfo)
    valid = d in [today, next_day] and datetime.time(10, 0) <= t <= datetime.time(19, 0) and stamp > now and not vars.get('close_attempted')
    if valid:
        config['body'] = dict(customer_id=vars['customer_id'], date=d.isoformat(), time=t.strftime('%H:%M'))
    else:
        config['body'] = {}
except Exception:
    config['body'] = {}

