close_call.pre_process_code:
import json
vars['close_state'] = 'failed'
try:
    s = vars.get('call_state', {})
    if isinstance(s, str):
        s = json.loads(s)
    outcome = str(vars.get('close_outcome', ''))
    reason = str(vars.get('close_reason', ''))
    allowed = dict(promise=[''], paid=[''], transferred=['restructuring','human','support'], no_promise=['refused','hardship','dispute','service_error'], not_verified=['failed','declined'], not_reached=['callback','no_callback','wrong_number','deceased','unclear'])
    valid = not vars.get('close_attempted') and outcome in allowed and reason in allowed[outcome]
    ps = s.get('products', [])
    if s.get('transfer_success'):
        expected_reason = dict(general='human', restructuring='restructuring', support='support')[s['transfer_success']]
        valid = valid and outcome == 'transferred' and reason == expected_reason and not any(p.get('noted') for p in ps)
    elif s.get('early_outcome'):
        valid = valid and outcome == s['early_outcome'] and reason == s.get('early_reason', '')
    else:
        valid = valid and vars.get('security_ready') == 'yes' and s.get('loaded') is True and len(ps) > 0 and all(p.get('status') == 'recorded' or p.get('noted') is True for p in ps)
        if any(p.get('status') == 'recorded' for p in ps):
            valid = valid and outcome == 'promise' and reason == ''
        elif ps and all(p.get('status') == 'paid' for p in ps):
            valid = valid and outcome == 'paid' and reason == ''
        elif ps:
            expected_reason = next(p.get('status') for p in ps if p.get('status') != 'paid')
            valid = valid and outcome == 'no_promise' and reason == expected_reason
    vars['close_attempted'] = 'yes'
    if valid:
        body = dict(customer_id=vars['customer_id'], outcome=outcome)
        if reason:
            body['reason'] = reason
        config['body'] = body
    else:
        config['body'] = {}
except Exception:
    vars['close_attempted'] = 'yes'
    config['body'] = {}

